import json
from pathlib import Path
from typing import Any

DEFAULT_CONFIG = {
    "debug": False,
    "timeout": 30,
    "max_retries": 3,
    "log_level": "INFO",
    "cache_dir": ".cache",
    "workers": 4,
    "host": "localhost",
    "port": 8080,
}

def load_config(path: str = "config.json") -> dict[str, Any]:
    """Load config from JSON file, returning defaults if file not found."""
    config_path = Path(path)

    if not config_path.exists():
        return DEFAULT_CONFIG.copy()

    try:
        with open(config_path) as f:
            return json.load(f)
    except json.JSONDecodeError:
        return DEFAULT_CONFIG.copy()

def get(key: str, path: str = "config.json", default: Any = None) -> Any:
    """Get a config value by key."""
    config = load_config(path)
    return config.get(key, default)

def merge_env_overrides(config: dict[str, Any], prefix: str = "APP_") -> dict[str, Any]:
    """Override config values with environment variables."""
    import os
    result = config.copy()
    for key in result:
        env_var = f"{prefix}{key.upper()}"
        if env_var in os.environ:
            value = os.environ[env_var]
            if value.lower() in ("true", "false"):
                result[key] = value.lower() == "true"
            elif value.isdigit():
                result[key] = int(value)
            else:
                result[key] = value
    return result
